parameters.functionCode:
const items = $input.all();
const requestData = items.find(item => item.json.recommendation_id)?.json;
const collaborativeResults = items.filter(item => item.json.algorithm === 'collaborative_filtering');
const contentResults = items.filter(item => item.json.algorithm === 'content_based');
const aiResult = items.find(item => item.json.choices);

const aiRecommendations = aiResult ? JSON.parse(aiResult.json.choices[0].message.content) : {};

// Create item score map
const itemScores = {};

// Add collaborative filtering scores
collaborativeResults.forEach(item => {
  const id = item.json.item_id;
  if (!itemScores[id]) {
    itemScores[id] = {
      item_id: id,
      item_name: item.json.item_name,
      category: item.json.category,
      tags: item.json.tags,
      scores: {},
      reasons: []
    };
  }
  itemScores[id].scores.collaborative = parseFloat(item.json.predicted_rating || 0) * 20;
  itemScores[id].reasons.push(`Recommended by ${item.json.user_count} similar users`);
});

// Add content-based scores
contentResults.forEach(item => {
  const id = item.json.item_id;
  if (!itemScores[id]) {
    itemScores[id] = {
      item_id: id,
      item_name: item.json.item_name,
      category: item.json.category,
      tags: item.json.tags,
      scores: {},
      reasons: []
    };
  }
  itemScores[id].scores.content_based = parseFloat(item.json.content_score || 0) * 20;
  itemScores[id].reasons.push(`Matches your interests in ${item.json.category}`);
});

// Add AI recommendations
(aiRecommendations.recommended_items || []).forEach(item => {
  const id = item.item_id;
  if (itemScores[id]) {
    itemScores[id].scores.ai_semantic = item.relevance_score || 85;
    itemScores[id].reasons.push(item.reasoning);
    itemScores[id].predicted_rating = item.predicted_rating;
  }
});

// Calculate hybrid scores (weighted average)
const hybridRecommendations = Object.values(itemScores).map(item => {
  const scores = item.scores;
  const weights = {
    collaborative: 0.35,
    content_based: 0.25,
    ai_semantic: 0.40
  };

  let hybridScore = 0;
  let totalWeight = 0;

  Object.entries(weights).forEach(([algorithm, weight]) => {
    if (scores[algorithm]) {
      hybridScore += scores[algorithm] * weight;
      totalWeight += weight;
    }
  });

  hybridScore = totalWeight > 0 ? hybridScore / totalWeight : 0;

  return {
    ...item,
    hybrid_score: parseFloat(hybridScore.toFixed(2)),
    confidence: totalWeight >= 0.6 ? 'high' : totalWeight >= 0.3 ? 'medium' : 'low',
    algorithms_used: Object.keys(scores),
    predicted_rating: item.predicted_rating || (hybridScore / 20).toFixed(1)
  };
}).sort((a, b) => b.hybrid_score - a.hybrid_score);

// Apply diversity filter to avoid recommending too many items from same category
const diverseRecommendations = [];
const categoryCount = {};
const maxPerCategory = Math.ceil(requestData.limit / 3);

hybridRecommendations.forEach(item => {
  const category = item.category;
  if ((categoryCount[category] || 0) < maxPerCategory && diverseRecommendations.length < requestData.limit) {
    diverseRecommendations.push(item);
    categoryCount[category] = (categoryCount[category] || 0) + 1;
  }
});

// Fill remaining slots if needed
if (diverseRecommendations.length < requestData.limit) {
  hybridRecommendations.forEach(item => {
    if (!diverseRecommendations.find(r => r.item_id === item.item_id) && 
        diverseRecommendations.length < requestData.limit) {
      diverseRecommendations.push(item);
    }
  });
}

const result = {
  recommendation_id: requestData.recommendation_id,
  timestamp: requestData.timestamp,
  user_id: requestData.user_id,
  recommendations: diverseRecommendations.slice(0, requestData.limit),
  algorithm_performance: {
    collaborative_filtering: {
      items_found: collaborativeResults.length,
      avg_score: collaborativeResults.length > 0 ?
        (collaborativeResults.reduce((sum, r) => sum + parseFloat(r.json.predicted_rating || 0), 0) / collaborativeResults.length).toFixed(2) : 0
    },
    content_based: {
      items_found: contentResults.length,
      avg_score: contentResults.length > 0 ?
        (contentResults.reduce((sum, r) => sum + parseFloat(r.json.content_score || 0), 0) / contentResults.length).toFixed(2) : 0
    },
    ai_semantic: {
      items_found: (aiRecommendations.recommended_items || []).length,
      explanation: aiRecommendations.explanation
    }
  },
  diversity_metrics: {
    unique_categories: Object.keys(categoryCount).length,
    category_distribution: categoryCount
  },
  metadata: {
    algorithms_used: requestData.algorithms,
    processing_time_ms: Date.now() - new Date(requestData.timestamp).getTime()
  }
};

return { json: result };
